Subroutine AplicarDescuento(total As Integer By Reference)
  total <- total - total Div 10;
EndSubroutine

Algorithm Caja
  Define total As Integer <- 0;
  total <- total + 3 * 3;
  total <- total + 5 * 2;
  AplicarDescuento(total);
  Write "Cobrado: ", total;
  AplicarDescuento(total);
  Write "Ticket: ", total;
EndAlgorithm

Function importe <- Linea(precio As Integer, cantidad As Integer)
  Define importe As Integer;
  importe <- precio * cantidad;
EndFunction

Function monto <- ConDescuento(total As Integer)
  Define monto As Integer;
  monto <- total - total Div 10;
EndFunction

Algorithm Caja
  Define aPagar As Integer <- ConDescuento(Linea(3, 3) + Linea(5, 2));
  Write "Cobrado: ", aPagar;
  Write "Ticket: ", aPagar;
  Write "Doble descuento: ", ConDescuento(ConDescuento(19));
EndAlgorithm

Function monto <- ConDescuento(total As Integer)
  Define monto As Integer;
  monto <- total - total Div 10;
EndFunction

Algorithm Casos
  Write ConDescuento(19), " ", ConDescuento(9), " ", ConDescuento(10), " ", ConDescuento(0);
EndAlgorithm
